(()=>{'use strict';function snippets(){document.querySelectorAll('.clarity-table tbody tr').forEach(row=>{const title=row.querySelector('[data-task],[data-shared-card]');if(!title)return;const t=tasks.find(t=>t.id===(title.dataset.task||title.dataset.sharedCard)),text=String(t?.description||'').trim();let snippet=row.querySelector('.task-description-preview');if(!text){snippet?.remove();return}if(!snippet){snippet=document.createElement('p');snippet.className='task-description-preview';title.after(snippet)}snippet.textContent=text;snippet.title=text})}const oldRender=render;render=function(...a){const r=oldRender(...a);snippets();return r};const oldTasks=renderTasks;renderTasks=function(...a){const r=oldTasks(...a);snippets();return r};snippets()})();
